import{_ as n,C as s,o as e,c as i,a2 as a,b as d,w as o,a as l,E as c,a3 as g}from"./chunks/framework.Dd_iHz3e.js";const k=JSON.parse('{"title":"14.16 Cloud Economics, Infrastructure Costs & Trade-Offs","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.16-cost-and-trade-offs.md","filePath":"system-design/14.16-cost-and-trade-offs.md"}'),u={name:"system-design/14.16-cost-and-trade-offs.md"};function h(m,t,p,f,b,v){const r=s("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="_14-16-cloud-economics-infrastructure-costs-trade-offs" tabindex="-1">14.16 Cloud Economics, Infrastructure Costs &amp; Trade-Offs <a class="header-anchor" href="#_14-16-cloud-economics-infrastructure-costs-trade-offs" aria-label="Permalink to &quot;14.16 Cloud Economics, Infrastructure Costs &amp; Trade-Offs&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Cloud economics evaluates the financial cost of running a software architecture at scale, balancing managed cloud services against raw infrastructure, and identifying the primary cost drivers (compute, database, AI tokens, network bandwidth, storage egress).</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>Pre-Trained AI via Gateway</strong>: Eliminates dedicated GPU server costs (~$1,050/mo base) by paying only for generated tokens (~$0.075 / 1M input tokens).</li><li><strong>Static Frontend on CDN</strong>: Hosted on zero-cost or low-cost edge CDNs (Vercel / Cloudflare).</li><li><strong>Decoupled Backend</strong>: Ingestion and database scale independently on standard x86 CPU containers.</li></ul><hr><h2 id="_3-monthly-cost-projection-current-vs-100x-scale" tabindex="-1">3. Monthly Cost Projection: Current vs 100x Scale <a class="header-anchor" href="#_3-monthly-cost-projection-current-vs-100x-scale" aria-label="Permalink to &quot;3. Monthly Cost Projection: Current vs 100x Scale&quot;">​</a></h2>',8)),(e(),d(g,null,{default:o(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"pie%20title%20Monthly%20Cloud%20Cost%20Drivers%20at%20100x%20Scale%20(Total%3A%20~%242%2C570%2Fmo)%0A%20%20%20%20%22Video%20Egress%20%26%20CDN%20(1.5%20Gbps)%22%20%3A%201100%0A%20%20%20%20%22AI%20Token%20Inference%20(Gemini%203%20Flash)%22%20%3A%20850%0A%20%20%20%20%22MongoDB%20Atlas%20Replica%20Set%20(M30)%22%20%3A%20380%0A%20%20%20%20%22Backend%20ECS%20Compute%20(Node.js)%22%20%3A%20180%0A%20%20%20%20%22S3%20Storage%20%26%20Transcoding%22%20%3A%2060%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h3 id="detailed-cost-breakdown-table" tabindex="-1">Detailed Cost Breakdown Table <a class="header-anchor" href="#detailed-cost-breakdown-table" aria-label="Permalink to &quot;Detailed Cost Breakdown Table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Infrastructure Component</th><th>Current Scale (MVP: 100 Daily Kitchens)</th><th>100x Scale (Production: 10,000 Active Kitchens)</th><th>Primary Cost Driver</th></tr></thead><tbody><tr><td><strong>Frontend Static Hosting</strong></td><td>$0 (Vercel Hobby / Cloudflare Pages)</td><td>$20/mo (Cloudflare Pro / Custom Domain)</td><td>Edge request volume</td></tr><tr><td><strong>Backend Compute (Express)</strong></td><td>$7/mo (Render / Railway starter)</td><td>$180/mo (4x AWS ECS Fargate containers)</td><td>CPU &amp; RAM for telemetry parsing</td></tr><tr><td><strong>MongoDB Database</strong></td><td>$0 (MongoDB Atlas Shared M0)</td><td>$380/mo (MongoDB Atlas Dedicated M30 Replica Set)</td><td>RAM cache, IOPS, multi-AZ storage</td></tr><tr><td><strong>Video Reel CDN Egress</strong></td><td>$5/mo (Low bandwidth)</td><td>$1,100/mo (Cloudflare R2 + CloudFront egress)</td><td>Video streaming bandwidth (1.5 Gbps)</td></tr><tr><td><strong>AI Tokens (Gemini 3 Flash)</strong></td><td>$15/mo (~100k queries)</td><td>$850/mo (~10M queries with semantic caching)</td><td>Generative AI chat &amp; recipe parsing</td></tr><tr><td><strong>Object Storage (S3 / R2)</strong></td><td>$2/mo (10 GB storage)</td><td>$40/mo (1 TB video &amp; photo storage)</td><td>Gigabytes stored</td></tr><tr><td><strong>Total Monthly Running Cost</strong></td><td><strong>~$29 / month</strong></td><td><strong>~$2,570 / month</strong></td><td><strong>Bandwidth &amp; AI Tokens</strong></td></tr></tbody></table><hr><h2 id="_4-build-vs-buy-analysis" tabindex="-1">4. Build vs Buy Analysis <a class="header-anchor" href="#_4-build-vs-buy-analysis" aria-label="Permalink to &quot;4. Build vs Buy Analysis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Decision</th><th>Rationale</th><th>Cost Impact</th></tr></thead><tbody><tr><td><strong>AI Inference</strong></td><td><strong>Buy (API)</strong></td><td>Training a custom model costs $20k+ with no guarantee of beating Gemini 3 Flash.</td><td>Saved ~$20,000 in upfront ML engineering</td></tr><tr><td><strong>Authentication</strong></td><td><strong>Build (JWT Magic)</strong></td><td>Building lightweight 15m JWT magic links eliminated Auth0/Clerk monthly active user charges ($0.05/MAU = $500/mo at 10k users).</td><td>Saved ~$6,000/year</td></tr><tr><td><strong>Video Player</strong></td><td><strong>Build (HTML5)</strong></td><td>Headless React component with Tailwind CSS avoided heavy $400/mo enterprise video player licensing.</td><td>Saved ~$4,800/year</td></tr><tr><td><strong>Database</strong></td><td><strong>Buy (Atlas Managed)</strong></td><td>Managing raw MongoDB on EC2 requires dedicated DBA staff for backups, failover, and OS patching.</td><td>Worth the $380/mo managed fee</td></tr></tbody></table><hr><h2 id="_5-vendor-lock-in-exit-strategy" tabindex="-1">5. Vendor Lock-In &amp; Exit Strategy <a class="header-anchor" href="#_5-vendor-lock-in-exit-strategy" aria-label="Permalink to &quot;5. Vendor Lock-In &amp; Exit Strategy&quot;">​</a></h2><ul><li><strong>Risk</strong>: Reliance on Lovable Gateway / Google Gemini 3 Flash.</li><li><strong>Exit Strategy</strong>: Our edge function uses the standard OpenAI-compatible <code>/chat/completions</code> API interface. If Google increases pricing or the gateway suffers an outage, switching to OpenAI GPT-4o mini, Mistral, or Groq Llama 3 requires changing only two environment variables (<code>API_KEY</code> and <code>ENDPOINT_URL</code>) with zero code alterations.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li>Video streaming egress bills can skyrocket unpredictably if users leave reels playing in background tabs.</li><li><strong>Defense</strong>: Enforce a 5-minute inactivity auto-pause on video feeds.</li></ul><hr><h2 id="_7-spoken-interview-answer-30-seconds" tabindex="-1">7. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_7-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;7. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;At 10,000 active kitchens, our projected operational cloud cost is approximately $2,570 a month, with video egress and AI tokens representing over 75% of the total spend. We kept our burn rate ultra-lean by making smart build-versus-buy decisions: we built our own passwordless JWT auth to avoid expensive per-MAU SaaS fees, while leveraging Google&#39;s Gemini 3 Flash via API rather than burning tens of thousands of dollars training a custom ML model.&quot;</p>',14))])}const A=n(u,[["render",h]]);export{k as __pageData,A as default};
